-- Team Relay demo schema draft for PostgreSQL 15+.
-- IDs and secret hashes are generated by the application. No plaintext invite
-- code or device token may be stored in this database.

BEGIN;

CREATE TABLE IF NOT EXISTS team_relay_schema_migrations (
    version varchar(64) PRIMARY KEY,
    applied_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE principals (
    id uuid PRIMARY KEY,
    display_name varchar(80) NOT NULL CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 80),
    created_at timestamptz NOT NULL DEFAULT now(),
    disabled_at timestamptz
);

CREATE TABLE teams (
    id uuid PRIMARY KEY,
    name varchar(120) NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 120),
    -- Null only between the server-admin bootstrap and first owner claim.
    created_by uuid REFERENCES principals(id) ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE devices (
    id uuid PRIMARY KEY,
    principal_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    name varchar(120) NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 120),
    token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    last_seen_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX devices_principal_active_idx
    ON devices (principal_id)
    WHERE revoked_at IS NULL;

CREATE TABLE memberships (
    team_id uuid NOT NULL REFERENCES teams(id) ON DELETE RESTRICT,
    principal_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    role varchar(16) NOT NULL CHECK (role IN ('owner', 'member')),
    joined_at timestamptz NOT NULL DEFAULT now(),
    removed_at timestamptz,
    PRIMARY KEY (team_id, principal_id)
);

CREATE INDEX memberships_principal_active_idx
    ON memberships (principal_id, team_id)
    WHERE removed_at IS NULL;

CREATE TABLE invites (
    id uuid PRIMARY KEY,
    team_id uuid NOT NULL REFERENCES teams(id) ON DELETE RESTRICT,
    token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    role varchar(16) NOT NULL CHECK (role IN ('owner', 'member')),
    created_by uuid REFERENCES principals(id) ON DELETE RESTRICT,
    expires_at timestamptz NOT NULL,
    claimed_at timestamptz,
    claimed_by uuid REFERENCES principals(id) ON DELETE RESTRICT,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at > created_at),
    CHECK ((claimed_at IS NULL) = (claimed_by IS NULL)),
    CHECK (claimed_at IS NULL OR claimed_at >= created_at),
    CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

CREATE INDEX invites_team_available_idx
    ON invites (team_id, expires_at)
    WHERE claimed_at IS NULL AND revoked_at IS NULL;

CREATE TABLE work_threads (
    id uuid PRIMARY KEY,
    team_id uuid NOT NULL REFERENCES teams(id) ON DELETE RESTRICT,
    title varchar(200) NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 200),
    initiator_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    owner_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    current_actor_id uuid REFERENCES principals(id) ON DELETE RESTRICT,
    return_to_id uuid REFERENCES principals(id) ON DELETE RESTRICT,
    final_recipient_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    phase varchar(32) NOT NULL CHECK (phase IN ('active', 'awaiting_acceptance', 'closed')),
    revision bigint NOT NULL CHECK (revision >= 1),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (
        (phase = 'active' AND current_actor_id IS NOT NULL AND return_to_id IS NOT NULL)
        OR
        (
            phase = 'awaiting_acceptance'
            AND current_actor_id = final_recipient_id
            AND return_to_id IS NULL
        )
        OR
        (phase = 'closed' AND current_actor_id IS NULL AND return_to_id IS NULL)
    )
);

CREATE INDEX work_threads_team_updated_idx
    ON work_threads (team_id, updated_at DESC);
CREATE INDEX work_threads_current_actor_idx
    ON work_threads (team_id, current_actor_id, updated_at DESC)
    WHERE phase <> 'closed';
CREATE INDEX work_threads_return_to_idx
    ON work_threads (team_id, return_to_id, updated_at DESC)
    WHERE phase = 'active';

CREATE TABLE thread_participants (
    thread_id uuid NOT NULL REFERENCES work_threads(id) ON DELETE RESTRICT,
    principal_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    first_action_sequence bigint NOT NULL CHECK (first_action_sequence >= 1),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (thread_id, principal_id)
);

CREATE INDEX thread_participants_principal_idx
    ON thread_participants (principal_id, thread_id);

CREATE TABLE relay_actions (
    id uuid PRIMARY KEY,
    thread_id uuid NOT NULL REFERENCES work_threads(id) ON DELETE RESTRICT,
    sequence bigint NOT NULL CHECK (sequence >= 1),
    kind varchar(32) NOT NULL CHECK (
        kind IN ('assign', 'note', 'handoff', 'return', 'final_deliver', 'request_changes', 'accept')
    ),
    actor_id uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    recipient_id uuid REFERENCES principals(id) ON DELETE RESTRICT,
    return_to_id uuid REFERENCES principals(id) ON DELETE RESTRICT,
    message text NOT NULL DEFAULT '' CHECK (char_length(message) <= 10000),
    base_revision bigint NOT NULL CHECK (base_revision >= 0),
    idempotency_key uuid NOT NULL,
    request_hash char(64) NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (thread_id, sequence),
    UNIQUE (actor_id, idempotency_key),
    CHECK (
        (kind = 'assign' AND recipient_id IS NOT NULL AND return_to_id IS NOT NULL)
        OR (kind = 'handoff' AND recipient_id IS NOT NULL AND return_to_id IS NOT NULL)
        OR (kind = 'return' AND recipient_id IS NOT NULL AND return_to_id IS NOT NULL)
        OR (kind = 'final_deliver' AND recipient_id IS NOT NULL AND return_to_id IS NULL)
        OR (kind = 'request_changes' AND recipient_id IS NOT NULL AND return_to_id IS NOT NULL)
        OR (kind IN ('note', 'accept') AND return_to_id IS NULL)
    )
);

CREATE INDEX relay_actions_thread_sequence_idx
    ON relay_actions (thread_id, sequence);

CREATE TABLE attachments (
    id uuid PRIMARY KEY,
    team_id uuid NOT NULL REFERENCES teams(id) ON DELETE RESTRICT,
    uploaded_by uuid NOT NULL REFERENCES principals(id) ON DELETE RESTRICT,
    upload_id uuid NOT NULL,
    storage_key varchar(255) NOT NULL UNIQUE,
    original_name varchar(255) NOT NULL CHECK (char_length(btrim(original_name)) BETWEEN 1 AND 255),
    content_type varchar(255) NOT NULL,
    byte_size bigint NOT NULL CHECK (byte_size >= 0 AND byte_size <= 20971520),
    sha256 char(64) NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    bound_at timestamptz,
    deleted_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (uploaded_by, upload_id)
);

CREATE INDEX attachments_team_created_idx
    ON attachments (team_id, created_at);
CREATE INDEX attachments_orphan_cleanup_idx
    ON attachments (created_at)
    WHERE bound_at IS NULL AND deleted_at IS NULL;
CREATE INDEX attachments_closed_cleanup_idx
    ON attachments (bound_at)
    WHERE bound_at IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE action_attachments (
    action_id uuid NOT NULL REFERENCES relay_actions(id) ON DELETE RESTRICT,
    attachment_id uuid NOT NULL REFERENCES attachments(id) ON DELETE RESTRICT,
    ordinal smallint NOT NULL CHECK (ordinal BETWEEN 0 AND 9),
    PRIMARY KEY (action_id, attachment_id),
    UNIQUE (action_id, ordinal),
    UNIQUE (attachment_id)
);

COMMENT ON TABLE relay_actions IS
    'Immutable action log. Application transactions keep sequence equal to the resulting thread revision.';
COMMENT ON COLUMN relay_actions.request_hash IS
    'SHA-256 of the canonical business request; detects idempotency-key reuse with different input.';
COMMENT ON COLUMN attachments.storage_key IS
    'Opaque server-generated key. Original filenames must never be used as filesystem paths.';

INSERT INTO team_relay_schema_migrations (version) VALUES ('0001_demo');

COMMIT;
